import { phoneMaxWidth, phoneTokens, tokens } from '../src/tokens.ts';

const declarations = (values: Readonly<Record<string, string>>, indent: string): string =>
  Object.entries(values).map(([name, value]) => `${indent}--${name}: ${value};`).join('\n');

/** Pure rendering shared by the writer and the read-only drift check. */
export function renderCss(): string {
  return `/*
 * Generated from packages/tokens/src/tokens.ts. Do not edit this file.
 * Regenerate with: pnpm --filter @app/tokens generate
 * Theme: Violet Observatory (docs/design.md). Existing token names must not be renamed.
 */
:root {
${declarations(tokens, '  ')}
}

@media (max-width: ${phoneMaxWidth}) {
  :root {
${declarations(phoneTokens, '    ')}
  }
}
`;
}
